fn head_run(xs: List[Int]) -> Int
  requires len(xs) >= 1
  ensures result >= 1
  ensures result <= len(xs)
  effects pure
  example head_run([1, 1, 2, 3]) == 2
  example head_run([5]) == 1
  example head_run([2, 2, 2]) == 3
{
  match xs {
    [] => 1
    [h, ..t] => match t {
      [] => 1
      [h2, ..t2] => if h == h2 then 1 + head_run(t) else 1
    }
  }
}

fn longest_run(xs: List[Int]) -> Int
  requires len(xs) >= 1
  ensures result >= 1
  ensures result <= len(xs)
  ensures result >= head_run(xs)
  effects pure
  example longest_run([1, 1, 2, 2, 2, 3]) == 3
  example longest_run([7]) == 1
  example longest_run([1, 2, 3]) == 1
  example longest_run([4, 4, 4, 4]) == 4
{
  match xs {
    [] => 1
    [h, ..t] => match t {
      [] => 1
      [h2, ..t2] => if head_run(xs) >= longest_run(t) then head_run(xs) else longest_run(t)
    }
  }
}

fn max_subarray(xs: List[Int]) -> Int
  requires len(xs) > 0
  requires exists x in xs: x > 0
  ensures result > 0
  effects pure
  example max_subarray([1, -2, 3, 4, -1]) == 7
  example max_subarray([2, 2, -5, 1]) == 4
{
  match xs {
    [] => 0
    [h, ..t] => kadane_impl(t, h, h)
  }
}

fn kadane_impl(xs: List[Int], max_so_far: Int, max_ending_here: Int) -> Int
  requires len(xs) >= 0
  ensures result >= max_so_far
  effects pure
  example kadane_impl([], 7, 6) == 7
  example kadane_impl([3, 4, -1], 1, -1) == 7
{
  match xs {
    [] => max_so_far
    [h, ..t] => kadane_impl(t, if (if h > (max_ending_here + h) then h else (max_ending_here + h)) > max_so_far then (if h > (max_ending_here + h) then h else (max_ending_here + h)) else max_so_far, if h > (max_ending_here + h) then h else (max_ending_here + h))
  }
}

fn max2(a: Int, b: Int) -> Int
  requires a == a and b == b
  ensures (result == a or result == b) and result >= a and result >= b
  effects pure
  example max2(3, 5) == 5
  example max2(-1, -2) == -1
{
  if a >= b then a else b
}

