fn kadane_helper(xs: List[Int], current_max: Int, global_max: Int) -> Int
  requires (len(xs) >= 0)
  ensures result >= global_max
  effects pure
  example (kadane_helper([], 0, 0) == 0)
{
  match xs {
    [] => global_max
    [h, ..t] =>
      if h >= current_max + h
      then
        if global_max >= h
        then kadane_helper(t, h, global_max)
        else kadane_helper(t, h, h)
      else
        if global_max >= current_max + h
        then kadane_helper(t, current_max + h, global_max)
        else kadane_helper(t, current_max + h, current_max + h)
  }
}

