fn argmax(xs: List[Int], original: List[Int]) -> Int
  requires len(xs) >= 1
  requires len(xs) <= len(original)
  ensures contains(xs, result)
  ensures forall x in xs: count(original, x) <= count(original, result)
  effects pure
  example argmax([1, 2, 2, 3], [1, 2, 2, 3]) == 2
  example argmax([5], [5]) == 5
  example argmax([4, 4, 4, 1, 2], [4, 4, 4, 1, 2]) == 4
{
  match xs {
    [] => 0
    [h, ..t] => match t {
      [] => h
      _ => if count_of(original, h) >= count_of(original, argmax(t, original))
             then h
             else argmax(t, original)
    }
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) == 0 or exists v in xs: forall y in xs: y == v or count(xs, y) < count(xs, v)
  ensures match result {
    None => len(xs) == 0
