fn find_most_frequent_helper(original: List[Int], remaining: List[Int], current_best: Int) -> Int
  requires contains(original, current_best) and forall x in remaining: contains(original, x)
  ensures contains(original, result) and forall y in original: count(original, y) <= count(original, result)
  effects pure
  example (find_most_frequent_helper([1, 2, 2, 3], [2, 2, 3], 1) == 2)
{
  match remaining {
    [] => current_best
    [h, ..t] => if count_occurrences(original, h) > count_occurrences(original, current_best) then
      find_most_frequent_helper(original, t, h)
    else
      find_most_frequent_helper(original, t, current_best)
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires ((len(xs) == 0) or (exists v in xs: forall y in xs: ((y == v) or (count(xs, y) < count(xs, v)))))
  ensures match result { None => (len(xs) == 0) Some(v) => (contains(xs, v) and (forall y in xs: (count(xs, y) <= count(xs, v)))) }
  effects pure
  example (most_frequent([1, 2, 2, 3]) == Some(2))
  example (most_frequent([]) == None)
  example (most_frequent([4, 4, 4, 1, 2]) == Some(4))
{
  match xs {
    [] => None
    [h, ..t] => Some(find_most_frequent_helper(xs, t, h))
  }
}

fn nth(xs: List[Int], i: Int) -> Option[Int]
  requires i >= 0
  ensures (i < len(xs)) or (result == None)
  ensures (i >= len(xs)) or (result != None)
  effects pure
  example nth([5, 6, 7], 1) == Some(6)
  example nth([5, 6, 7], 3) == None
  example nth([], 0) == None
  example nth([42], 0) == Some(42)
  example nth([1, 2, 3], 0) == Some(1)
{
  if i == 0 then match xs {
    [] => None
    [h, ..t] => Some(h)
  } else match xs {
    [] => None
    [_, ..t] => nth(t, i - 1)
  }
}

fn power(base: Int, exp: Int) -> Int
  requires exp >= 1
  ensures exp == 1 and result == base or exp > 1 and result == base * power(base, exp - 1)
  effects pure
  example power(2, 10) == 1024
  example power(-3, 3) == -27
  example power(5, 1) == 5
{
  if exp == 1 then base else base * power(base, exp - 1)
}

fn power(base: Int, exp: Int) -> Int
  requires (exp >= 1)
  ensures (((exp == 1) and (result == base)) or ((exp > 1) and (result == (base * power(base, (exp - 1))))))
  effects pure
  example (power(2, 10) == 1024)
  example (power(-3, 3) == -27)
  example (power(5, 1) == 5)
{
  if exp == 1 then base else base * power(base, exp - 1)
}

fn max_element(xs: List[Int]) -> Option[Int]
  requires len(xs) > 0
  ensures match result {
    None => false
    Some(m) => contains(xs, m) and forall x in xs: x <= m
  }
  effects pure
  example max_element([3, 9, 1]) == Some(9)
  example max_element([5]) == Some(5)
{
  match xs {
    [] => None
    [h, ..t] => 
      match t {
        [] => Some(h)
        _ => match max_element(t) {
          None => Some(h)
          Some(m) => if h > m then Some(h) else Some(m)
        }
      }
  }
}

fn remove_element(xs: List[Int], v: Int) -> List[Int]
  requires contains(xs, v)
  ensures len(result) == len(xs) - 1
  effects pure
  example remove_element([3, 9, 1], 9) == [3, 1]
  example remove_element([1, 2], 2) == [1]
  example remove_element([5], 5) == []
{
  match xs {
    [] => []
    [h, ..t] => 
      if h == v then t 
      else [h] ++ remove_element(t, v)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result {
    None => len(xs) < 2
    Some(x) => contains(xs, x) and exists y in xs: y > x
  }
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([1, 2]) == Some(1)
  example second_largest([]) == None
{
  match xs {
    [] => None
    [_, ..t] => 
      match t {
        [] => None
        _ => match max_element(xs) {
          None => None
          Some(m) => max_element(remove_element(xs, m))
        }
      }
  }
}

fn max(xs: List[Int]) -> Int
  requires len(xs) >= 1
  ensures contains(xs, result)
  ensures forall x in xs: x <= result
  effects pure
  example max([3, 9, 1]) == 9
  example max([5]) == 5
  example max([1, 2]) == 2
{
  match xs {
    [] => 0
    [h, ..t] => match t {
      [] => h
      [h2, ..t2] => if h >= max(t) then h else max(t)
    }
  }
}

fn remove_one(xs: List[Int], v: Int) -> List[Int]
  requires contains(xs, v)
  ensures len(result) == len(xs) - 1
  ensures forall x in result: contains(xs, x)
  ensures forall x in xs: x == v or contains(result, x)
  effects pure
  example remove_one([3, 9, 1], 9) == [3, 1]
  example remove_one([4], 4) == []
{
  match xs {
    [] => []
    [h, ..t] => if h == v then t else [h] ++ remove_one(t, v)
  }
}

fn has_at_least_two(xs: List[Int]) -> Bool
  requires len(xs) >= 0
  ensures result == (len(xs) >= 2)
  effects pure
  example has_at_least_two([]) == false
  example has_at_least_two([1]) == false
  example has_at_least_two([1, 2]) == true
{
  match xs {
    [] => false
    [h, ..t] => match t {
      [] => false
      [h2, ..t2] => true
    }
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures len(xs) >= 2 or result == None
  ensures len(xs) < 2 or (match result {
    None => false
    Some(v) => contains(xs, v) and v != max(xs) and (forall x in xs: x == max(xs) or x <= v)
  })
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
{
  if has_at_least_two(xs) then Some(max(remove_one(xs, max(xs)))) else None
}

fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires len(xs) == len(ys)
  ensures len(result) == len(xs)
  effects pure
  example zip_sum([], []) == []
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
{
  match xs {
    [] => []
    [h_x, ..t_x] => 
      match ys {
        [h_y, ..t_y] => [h_x + h_y] ++ zip_sum(t_x, t_y)
        [] => []
      }
  }
}

fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires len(xs) == len(ys)
  ensures len(result) == len(xs)
  ensures is_pointwise_sum(xs, ys, result)
  effects pure
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
  example zip_sum([], []) == []
  example zip_sum([5], [7]) == [12]
{
  match xs {
    [] => []
    [hx, ..tx] => match ys {
      [] => []
      [hy, ..ty] => [hx + hy] ++ zip_sum(tx, ty)
    }
  }
}

fn is_pointwise_sum(xs: List[Int], ys: List[Int], result: List[Int]) -> Bool
