  ensures (contains(original, result) and (forall y in original: (count(original, y) <= count(original, result))))
  effects pure
  example (find_most_frequent_helper([1, 2, 2, 3], [2, 2, 3], 1) == 2)
{
  match remaining { [] => current_best [h, ..t] => if (count_occurrences(original, h) > count_occurrences(original, current_best)) then find_most_frequent_helper(remaining, t, h) else find_most_frequent_helper(original, t, current_best) }
}

