fn max_element(xs: List[Int]) -> Option[Int]
  requires (len(xs) > 0)
  ensures match result { None => false Some(m) => (contains(xs, m) and (forall x in xs: (x <= m))) }
  effects pure
  example (max_element([3, 9, 1]) == Some(9))
  example (max_element([5]) == Some(5))
{
  match xs { [] => None [h, ..t] => match t { [] => Some(h) _ => match max_element(t) { None => Some(h) Some(m) => if (h >= m) then Some(h) else Some(m) } } }
}

fn remove_element(xs: List[Int], v: Int) -> List[Int]
  requires contains(xs, v)
  ensures (len(result) == (len(xs) - 1))
  effects pure
  example (remove_element([3, 9, 1], 9) == [3, 1])
  example (remove_element([1, 2], 2) == [1])
  example (remove_element([5], 5) == [])
{
  match xs { [] => [] [h, ..t] => if (h == v) then t else ([h] ++ remove_element(t, v)) }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => (len(xs) < 2) Some(x) => (contains(xs, x) and (exists y in xs: (y > x))) }
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([1, 2]) == Some(1))
  example (second_largest([]) == None)
{
  match xs { [] => None [_, ..t] => match t { [] => None _ => match max_element(xs) { None => None Some(m) => max_element(remove_element(xs, m)) } } }
}

