fn max(xs: List[Int]) -> Int
  requires (len(xs) >= 1)
  ensures contains(xs, result)
  ensures forall x in xs: (x <= result)
  effects pure
  example (max([3, 9, 1]) == 9)
  example (max([5]) == 5)
  example (max([1, 2]) == 2)
{
  match xs { [] => 0 [h, ..t] => match t { [] => h [h2, ..t2] => if (h >= max(t)) then h else max(t) } }
}

fn max_excluding(xs: List[Int], exclude: Int) -> Option[Int]
  requires (len(xs) >= 1)
  ensures match result { None => forall x in xs: (x == exclude) Some(v) => ((contains(xs, v) and (v != exclude)) and (forall x in xs: ((x == exclude) or (x <= v)))) }
  effects pure
  example (max_excluding([1, 2, 3], 4) == Some(3))
  example (max_excluding([1, 2], 2) == Some(1))
  example (max_excluding([4, 4, 4], 4) == None)
{
  match xs { [] => None [h, ..t] => if (h == exclude) then match t { [] => None [_, ..t2] => max_excluding(t, h) } else match t { [] => Some(h) [_, ..t2] => match max_excluding(t, exclude) { None => Some(h) Some(v) => Some(if (h >= v) then h else v) } } }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures ((len(xs) >= 2) or (result == None))
  ensures ((len(xs) < 2) or (match result { None => false Some(v) => ((contains(xs, v) and (v != max(xs))) and (forall x in xs: ((x == max(xs)) or (x <= v)))) }))
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
{
  match xs { [] => None [h, ..t] => match t { [] => None _ => max_excluding(xs, max(xs)) } }
}

